import { describe, expect, it } from 'vitest';

import { normalizePunctuation, normalizeSpaces, pairQuotes, toHalfWidth } from '../src/text';

describe('toHalfWidth', () => {
  it('全角字母数字转半角', () => {
    expect(toHalfWidth('ＡＢＣ１２３')).toBe('ABC123');
  });

  it('全角标点保持不变', () => {
    expect(toHalfWidth('你好，世界。')).toBe('你好，世界。');
  });
});

describe('normalizePunctuation', () => {
  it('孤立英文标点转中文 (夹在中文间)', () => {
    expect(normalizePunctuation('你好,世界')).toBe('你好，世界');
    expect(normalizePunctuation('他说:什么')).toBe('他说：什么');
  });

  it('连续非中文块整体保留 (字符与标点混合)', () => {
    expect(normalizePunctuation('Hello,world!')).toBe('Hello,world!');
    expect(normalizePunctuation('a:b;c?')).toBe('a:b;c?');
    expect(normalizePunctuation('(test)')).toBe('(test)');
    expect(normalizePunctuation('123abc%&*')).toBe('123abc%&*');
    expect(normalizePunctuation('assa!!!!!')).toBe('assa!!!!!');
    expect(normalizePunctuation('什么?!')).toBe('什么?!');
  });

  it('小数点的句号不被误转', () => {
    expect(normalizePunctuation('3.14')).toBe('3.14');
    expect(normalizePunctuation('3.14。')).toBe('3.14。');
  });

  it('省略号整体转换', () => {
    expect(normalizePunctuation('他说...')).toBe('他说……');
    expect(normalizePunctuation('a.b.c')).toBe('a.b.c');
  });

  it('URL 内部标点不受影响', () => {
    expect(normalizePunctuation('见 https://example.com/a.b 了解')).toBe('见 https://example.com/a.b 了解');
  });
});

describe('normalizeSpaces', () => {
  it('连续中文与非中文之间插入空格', () => {
    expect(normalizeSpaces('价格是12%的人')).toBe('价格是 12% 的人');
    expect(normalizeSpaces('abc中文')).toBe('abc 中文');
  });

  it('中文标点与两侧不加空格', () => {
    expect(normalizeSpaces('内容12%，继续')).toBe('内容 12%，继续');
  });

  it('清理多余空格', () => {
    expect(normalizeSpaces('  你好    世界  ')).toBe('你好 世界');
  });
});

describe('pairQuotes', () => {
  it('直引号配对外层双引号', () => {
    expect(pairQuotes('"你好"', () => {}).text).toBe('“你好”');
    expect(pairQuotes('他说"你好"', () => {}).text).toBe('他说“你好”');
  });

  it('里外都用双引号时识别嵌套', () => {
    expect(pairQuotes('“他说“你好”然后走了”', () => {}).text).toBe('“他说‘你好’然后走了”');
  });

  it('单引号在外时规范为外层双引号', () => {
    expect(pairQuotes("'你好'", () => {}).text).toBe('“你好”');
  });

  it('英文所有格撇号不作为引号', () => {
    expect(pairQuotes("It's fine", () => {}).text).toBe("It's fine");
  });

  it('未闭合引号产生报告', () => {
    const reports: string[] = [];
    pairQuotes('"你好', (m) => reports.push(m));
    expect(reports.some((m) => m.includes('未闭合'))).toBe(true);
  });
});
